# এসএসসি সাধারণ গণিত অধ্যায় ৪ (সূচক ও লগারিদম): আরও ২০টি সৃজনশীল প্রশ্ন — সহজ ৬, মধ্যম ১০, কঠিন ৪; ক (২), খ (৪), গ (৪)
# প্রতিটির ex: বিষয় অনুযায়ী ৪.১ / ৪.২ / ৪.৩, একাধিক অনুশীলনী মিশলে 'সমন্বিত'।
# gen_cq_c10_4.py এটি import করে cq_c10_4.json এ b11 থেকে যোগ করে।
import math, sympy as sp
from sympy import Rational as R, sqrt, log
x,y,z,n,k=sp.symbols('x y z n k',positive=True)
a,b,c=sp.symbols('a b c',positive=True)
E=lambda p,q: sp.simplify(p-q)==0
Q=lambda p,q: abs(sp.N(p-q,30))<1e-20
L=math.log10

# ---------- যাচাই: সহজ ----------
assert E(3**(n+2)-3**n,8*3**n) and E(3**(n+1)-3**n,2*3**n) and E((3**(n+2)-3**n)/(3**(n+1)-3**n),4) and sp.solve(8*3**n-216,n)==[3]
assert 2**3==8 and 3**4==81 and 2**7==128 and sqrt(2)**6==8 and 3**3==3**(4-1)
assert log(8,2)==3 and 3**2==9 and log(9,3)==2 and log(8,2)==3 and 3-2+4==5 and sp.simplify(log(9)/log(sqrt(3)))==4
l2,l3=0.3010,0.4771; assert round(2*l2,4)==0.6020 and round(2*l2+l3,4)==1.0791 and round(l2+l3-1,4)==-0.2219 and round((l2+2*l3)/2,4)==0.6276 and round(1-l2,4)==0.6990
assert abs(0.000276-2.76e-4)<1e-15 and 58300==5.83e4 and abs(0.000276*58300-16.0908)<1e-9 and math.floor(L(0.000276))==-4 and math.floor(L(58300))==4 and math.floor(L(16.0908))==1
assert 2**5==32 and log(8,2)==3 and sp.simplify(log(10,10)+log(R(1,5),5))==0
# ---------- যাচাই: মধ্যম ----------
assert sp.solve([2*x-3*y,x+2*y-7],[x,y])=={x:3,y:2} and 9**3==27**2 and 2**3*4**2==128 and 3**(3-2)+2**(3+2)==35
assert 2**6==64 and 4**2==16==2*8 and 4**3==64 and 8**2==64 and R(1,6)+R(1,2)==R(2,3)
f=lambda t:sp.Integer(2)**t+sp.Integer(2)**(-t); assert f(1)==R(5,2) and all(Q(f(sp.Rational(v,7))**2-2,f(2*sp.Rational(v,7))) for v in (3,-5,11)) and set(sp.solve(4*y**2-17*y+4,y))=={4,R(1,4)} and f(2)==f(-2)==R(17,4)
assert set(sp.solve(x**2-5*x+10-4,x))=={2,3} and E(log(3,2)*log(8,3),3)
assert round(3*l2+2*l3,4)==1.8572 and round(l3+1-l2,4)==1.1761 and round(l2+2*l3-1,4)==0.2552 and round((1+l3-l2)/(l2+l3),2)==1.51 and round(L(15)/L(6),2)==1.51
X=log(5,3); Y=log(27,25); assert E(X*Y,R(3,2)) and E(log(45,5),2/X+1)
assert round(l3/(2*l2),4)==0.7925 and round(l2+l3,4)==0.7781 and Q(3**R(3,2),3*sqrt(3))
assert sp.solve([x+y-3,x-y-1],[x,y])=={x:2,y:1} and log(1000,10)==3 and Q(100**log(10,10),10**log(100,10))
N_=0.0005432; assert abs(L(5.432)-0.7350)<1e-4 and math.floor(L(N_))==-4 and round(-4+0.7350,4)==-3.2650 and round(2*-3.2650,4)==-6.53 and round(-6.53+7,4)==0.47
assert (2*2)**2==2**(2*2) and sp.solve(2*x-x**2,x)==[2]; assert 4**2==2**4 and log(4,2)==2 and sp.simplify(log(2,4)+log(4,2))==R(5,2) and sp.solve(2*x-(x+3),x)==[3]
# ---------- যাচাই: কঠিন ----------
assert E(k**1*k**2*k**-3,1) and E(k**1*k**2,1/k**-3) and E(k**2,(k**1)**2)
la,lb,lc=sp.symbols('la lb lc')
assert sp.expand(a*(b-c)+b*(c-a)+c*(a-b))==0 and sp.expand((b+c)*(b-c)+(c+a)*(c-a)+(a+b)*(a-b))==0 and sp.expand((b-c)+(c-a)+(a-b))==0
assert abs(1+1/(l2/l3)-1/(l2/(l2+l3)))<1e-9 and round(l2/l3,3)==0.631 and round(l2/(l2+l3),3)==0.387 and round(l3/l2,3)==1.585 and round((l2+l3)/l2,3)==2.585
A=2; xa=log(A,2*A); ya=log(2*A,3*A); za=log(3*A,4*A)
assert Q(xa,R(1,2)) and Q(xa*ya*za,R(1,3)) and Q(ya*za,R(2,3)) and Q(xa*ya*za+1,2*ya*za)
xs=log(a,2*a); ys=log(2*a,3*a); zs=log(3*a,4*a); assert Q((xs*ys*zs+1-2*ys*zs).subs(a,7),0) and Q((xs*ys*zs+1-2*ys*zs).subs(a,R(5,3)),0)

